import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    with io.StringIO(raw_csv, newline="") as stream:
        rows = list(csv.reader(
            stream,
            delimiter=",",
            quotechar='"',
            doublequote=True,
            skipinitialspace=True,
            strict=False,
        ))

    if not rows:
        return {"columns": [], "rows": []}

    width = max(1, max(map(len, rows)))
    for row in rows:
        row.extend([""] * (width - len(row)))

    return {
        "columns": [f"column_{index}" for index in range(1, width + 1)],
        "rows": rows,
    }
